package com.study.module.system.guardian.controller;
import com.study.common.core.domain.Result; import com.study.common.core.utils.ResultUtils; import com.study.module.system.guardian.dto.response.GuardianWeeklyReportResp; import com.study.module.system.guardian.service.GuardianWeeklyReportService; import io.swagger.annotations.Api; import io.swagger.annotations.ApiOperation; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
